import { forwardRef, type InputHTMLAttributes } from 'react';

export type RadioProps = {
  checked?: boolean;
  disabled?: boolean;
  error?: boolean;
  label?: string;
  className?: string;
  onChange?: (checked: boolean) => void;
} & Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'checked' | 'onChange'>;

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export const Radio = forwardRef<HTMLInputElement, RadioProps>(
  (
    {
      checked = false,
      disabled = false,
      error = false,
      label,
      className,
      onChange,
      ...props
    },
    ref,
  ) => {
    const classes = cn(
      'radio',
      disabled && 'radio--disabled',
      error && 'radio--error',
      className,
    );

    return (
      <label className={classes}>
        <input
          ref={ref}
          type="radio"
          className="radio__input"
          checked={checked}
          disabled={disabled}
          onChange={(e) => onChange?.(e.target.checked)}
          {...props}
        />
        <span className="radio__circle">
          <span className="radio__dot" />
        </span>
        {label && <span className="radio__label">{label}</span>}
      </label>
    );
  },
);

Radio.displayName = 'Radio';

/* -------------------------------------------------------------------------
   Radio

   Single size (16px circle, 40px touch target).
   Native <input type="radio"> hidden, visual replacement via label.
   Shares color tokens with Checkbox (same palette).

   States:  unchecked, checked, disabled, error
   ------------------------------------------------------------------------- */

.radio {
  display: inline-flex;
  align-items: center;
  gap: 0.5em;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  position: relative;
}

.radio--disabled {
  cursor: not-allowed;
  pointer-events: none;
}

/* Hidden native input with touch target */
.radio__input {
  position: absolute;
  width: 2.5rem;
  height: 2.5rem;
  margin: 0;
  padding: 0;
  opacity: 0;
  cursor: inherit;
  left: -0.75rem;
  top: 50%;
  transform: translateY(-50%);
}

/* Visual circle */
.radio__circle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
  border-radius: var(--radius-full);
  border: var(--stroke-thin) solid var(--checkbox-border-default);
  background-color: var(--checkbox-bg-unchecked);
  transition:
    background-color var(--duration-150) var(--easing-out),
    border-color var(--duration-150) var(--easing-out),
    box-shadow var(--duration-150) var(--easing-out);
}

/* Inner dot */
.radio__dot {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: var(--radius-full);
  background-color: var(--checkbox-fg-checked);
  transform: scale(0);
  transition: transform var(--duration-150) var(--easing-out);
}

/* ---- Hover ---- */

.radio__input:hover:not(:disabled) ~ .radio__circle {
  background-color: var(--checkbox-bg-unchecked-hover);
}

.radio__input:checked:hover:not(:disabled) ~ .radio__circle {
  background-color: var(--checkbox-bg-checked-hover);
}

/* ---- Checked ---- */

.radio__input:checked ~ .radio__circle {
  background-color: var(--checkbox-bg-checked);
  border-color: var(--checkbox-bg-checked);
}

.radio__input:checked ~ .radio__circle .radio__dot {
  transform: scale(1);
}

/* ---- Focus ---- */

.radio__input:focus-visible ~ .radio__circle {
  box-shadow: 0 0 0 var(--stroke-medium) var(--checkbox-focus-ring-default);
}

/* ---- Disabled ---- */

.radio__input:disabled ~ .radio__circle {
  background-color: var(--checkbox-bg-disabled);
  border-color: var(--checkbox-bg-disabled);
}

.radio__input:disabled ~ .radio__circle .radio__dot {
  background-color: var(--checkbox-fg-disabled);
}

/* ---- Error ---- */

.radio--error .radio__circle {
  border-color: var(--checkbox-border-error);
}

/* ---- Label ---- */

.radio__label {
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-sm);
  line-height: 1;
  color: var(--foreground);
}

.radio--disabled .radio__label {
  color: var(--muted-foreground);
}

